(async () => {
  const tick = () => new Promise(resolve => requestAnimationFrame(resolve));
  const settle = async () => { for (let i=0;i<4;++i) await tick(); };
  document.documentElement.style.cssText='scroll-behavior:auto';
  document.body.style.cssText='margin:0;height:3000px';
  const frame=document.createElement('iframe');
  frame.style.cssText='display:block;width:320px;height:100px;border:0';
  document.body.append(frame);
  const child=frame.contentWindow;
  child.document.open();child.document.write('<!doctype html><html style="overflow:hidden"><body style="height:2000px;margin:0"></body>');child.document.close();
  child.innerWidth;
  await settle();
  let events=[];
  const rows=[];
  const query=child.matchMedia('(min-width:400px)');
  child.addEventListener('resize',()=>events.push(['resize',child.innerWidth]));
  child.visualViewport.addEventListener('resize',()=>events.push(['visual',child.visualViewport.width]));
  query.addEventListener('change',e=>events.push(['media',e.matches]));
  document.addEventListener('scroll',()=>events.push(['scroll',scrollY]));
  document.addEventListener('scrollend',()=>events.push(['scrollend',scrollY]));
  child.document.addEventListener('scroll',()=>events.push(['child-scroll',child.scrollY]));
  child.document.addEventListener('scrollend',()=>events.push(['child-scrollend',child.scrollY]));
  frame.style.width='480px';child.innerWidth;
  scrollTo(0,10);scrollTo(0,20);child.scrollTo(0,15);
  requestAnimationFrame(()=>events.push(['raf']));
  await settle();
  rows.push(['phases',events]);events=[];
  let reentered=false;
  document.addEventListener('scroll',()=>{
    if(reentered)return;
    reentered=true;
    scrollTo(0,40);
    Promise.resolve().then(()=>events.push(['microtask']));
  });
  scrollTo(0,30);
  requestAnimationFrame(()=>events.push(['raf']));
  await settle();
  rows.push(['reentrant',events]);events=[];
  const pane=document.createElement('div');
  pane.style.cssText='overflow:auto;width:100px;height:100px';
  pane.innerHTML='<div style="height:600px"></div>';
  document.body.append(pane);pane.getBoundingClientRect();await settle();events=[];
  pane.addEventListener('scroll',()=>events.push(['element-scroll',pane.scrollTop]));
  pane.addEventListener('scrollend',()=>events.push(['element-scrollend',pane.scrollTop]));
  pane.scrollTop=10;pane.scrollTop=20;
  requestAnimationFrame(()=>events.push(['raf']));await settle();
  rows.push(['element',events]);
  return {rows,failures:[]};
})()
